package io.github.diodeme.ji.ai;

/** Ordered events from one provider stream. */
public sealed interface ModelStreamEvent permits ModelStreamEvent.Started, ModelStreamEvent.TextDelta,
        ModelStreamEvent.ToolCallReady, ModelStreamEvent.Completed, ModelStreamEvent.Failed {
    record Started(String responseId) implements ModelStreamEvent {}
    record TextDelta(String text) implements ModelStreamEvent {}
    record ToolCallReady(Content.ToolCall toolCall) implements ModelStreamEvent {}
    record Completed(Usage usage, StopReason stopReason) implements ModelStreamEvent {}
    record Failed(ProviderFailure failure) implements ModelStreamEvent {}

    enum StopReason { STOP, TOOL_USE, ABORTED }
}
